def _build_component_06():
    def rounded(numerator, mode):
        denominator = 10000
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        rows_by_version = {
            name: {row["version"]: row for row in packages[name]}
            for name in names
        }
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = [[None] + sorted(rows_by_version[name]) for name in names]
        best_vector = None
        best_versions = None

        for values in product(*choices):
            installed = {name: version for name, version in zip(names, values)
                         if version is not None}
            valid = True
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in installed.items():
                if version in blocked.get(name, []):
                    valid = False
                    break
                if name in pins and version != pins[name]:
                    valid = False
                    break
            if not valid:
                continue

            graph = {}
            constraints_ok = True
            for name, version in installed.items():
                row = rows_by_version[name][version]
                graph[name] = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    dep_version = installed.get(target)
                    if (dep_version is None or
                            not dep["min"] <= dep_version <= dep["max"]):
                        constraints_ok = False
                        break
                    graph[name].append(target)
                if not constraints_ok:
                    break
            if not constraints_ok:
                continue

            # Only packages reachable through active dependencies and roots may be installed.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph.get(name, []))
            if reachable != set(installed):
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for target in graph.get(name, []):
                    if not visit(target):
                        return False
                state[name] = 2
                return True

            if not all(visit(name) for name in reachable):
                continue

            vector = tuple(installed.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = installed

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = required_bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        start = data["start"]
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                possibilities = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    possibilities.append((duration, remaining - 1))
                for duration, next_remaining in possibilities:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


